class MicroBatcher:
    def __init__(self, flush, max_size, max_age, clock):
        if not callable(flush):
            raise ValueError("Flush must be callable")
        if type(max_size) is not int or max_size < 1:
            raise ValueError("Max size must be positive")
        if type(max_age) not in (int, float) or max_age <= 0:
            raise ValueError("Max age must be positive")
        self._flush = flush
        self._max_size = max_size
        self._max_age = max_age
        self._clock = clock
        self._items = []
        self._first = None
        self._sent = 0

    @property
    def pending(self):
        return len(self._items)

    @property
    def batches_sent(self):
        return self._sent

    def _send(self):
        batch = self._items
        first = self._first
        self._items = []
        self._first = None
        try:
            self._flush(list(batch))
        except Exception:
            self._items = batch + self._items
            self._first = first
            raise
        self._sent += 1

    def add(self, item):
        now = self._clock()
        if not self._items:
            self._first = now
        self._items.append(item)
        if len(self._items) >= self._max_size:
            self._send()
            return True
        return False

    def tick(self):
        now = self._clock()
        if self._items and now - self._first >= self._max_age:
            self._send()
            return True
        return False

    def flush_now(self):
        self._clock()
        if not self._items:
            return False
        self._send()
        return True
